arguments.rule_content:
rule sigma rule_name: "ET TROJAN Cobalt Strike Beacon C2 Activity" {
  metadata: "https://github.com/Elastic/Detection-Rules/blob/main/rules/et/trojan/cobalt_strike_beacon_c2.yml"
  description: "Detects Cobalt Strike Beacon C2 activity"
  reference: "https://www.elastic.co/security-labs/cobalt-strike"
  author: "Elastic Security Team"
  date: "2023-02-15"
  tags: "cobalt strike, beacon, c2, elasticsearch"
  detection: {
    selection: {
      process.name: "csc.exe"
    }
    condition: 1
  }
  falsepositives: "None"
  level: "critical"
}

